/* walkdemo — ARCADE-1 walking-spritesheet experiment.
 *
 * A 40x56 4-bit character blitted from a 7-frame sheet (1 idle + a 6-step
 * walk cycle), walking left/right on flat ground at 60 fps. The sheet is
 * generated by tools/gen_walk_sheet.py into walkdemo_sheet.h — art reaches
 * the ROM only as data compiled from source, there is no asset pipeline.
 * Findings and measurements: docs/experiments/walkdemo.md.
 *
 * The four globals below are what the test reads back:
 *   arcade1 run walkdemo.arc1 --frames N --input script.txt \
 *       --syms walkdemo.syms --vars x,facing,anim,moving --capture f.ppm
 */
#include "arcade1.h"
#include "walkdemo_sheet.h"

#define SCREEN_W 480
#define SCREEN_H 270
#define GROUND_Y 200       /* the feet line the character stands on */
#define SPEED    2         /* px per frame */
#define WALK_TICK 4        /* frames per animation step (~15 steps/s) */
#define MIN_X    4
#define MAX_X    (SCREEN_W - WALK_FRAME_W - 4)

/* RGB565 components, spelled out so they are readable: (r5,g6,b5). */
#define SKY   ((4u << 11) | (12u << 5) | 28u)   /* dusk blue */
#define EDGE  ((12u << 11) | (48u << 5) | 16u)  /* ground edge highlight */
#define GRASS ((4u << 11) | (28u << 5) | 8u)    /* dark green */

int x = 20;       /* left edge of the character */
int facing = 0;   /* 0 = right, 1 = left (flip X, free in the blitter) */
int anim = 0;     /* sheet frame: 0 idle, 1..6 walk cycle */
int moving = 0;   /* 1 while a direction is held */

static int tick;  /* frames since the last animation step */
static int dir = 1;   /* cycle direction: +1 through the sheet, -1 back */
static int was_moving;   /* previous frame's moving flag (for the step-off) */

static void upload_palette(void)
{
    int i;

    for (i = 0; i < 16; i++)
        arcade1_pal(WALK_BANK * 16 + i, walk_pal[i]);
}

static void draw(void)
{
    arcade1_clear(SKY);
    arcade1_rect(0, GROUND_Y, SCREEN_W, 2, EDGE);
    arcade1_rect(0, GROUND_Y + 2, SCREEN_W, SCREEN_H - GROUND_Y - 2, GRASS);
    arcade1_sprite4(x, GROUND_Y - WALK_FRAME_H + 2,
                    walk_sheet + anim * WALK_STRIDE,
                    WALK_FRAME_W, WALK_FRAME_H, WALK_BANK,
                    facing ? 1u : 0u);      /* flags bit0 = flip X */
    arcade1_present();
}

int main(void)
{
    upload_palette();

    for (;;) {
        unsigned pad = arcade1_pad();

        moving = 0;
        if (pad & BTN_RIGHT) { x += SPEED; facing = 0; moving = 1; }
        if (pad & BTN_LEFT)  { x -= SPEED; facing = 1; moving = 1; }
        if (x < MIN_X) x = MIN_X;
        if (x > MAX_X) x = MAX_X;

        if (moving) {
            if (!was_moving) {               /* step off in the contact pose,
                                              * not 3 frames of idle pose */
                anim = 1;
                dir = 1;
                tick = 0;
            }
            if (++tick >= WALK_TICK) {       /* advance the walk cycle */
                tick = 0;
                anim += dir;
                if (anim >= WALK_FRAMES - 1)
                    dir = -1;                /* bounce: end of the sheet */
                else if (anim <= 1)
                    dir = 1;                 /* bounce: back at the start */
            }
        } else {
            anim = 0;                        /* stand when nothing is held */
            tick = 0;
        }
        was_moving = moving;

        draw();
    }
}
